import{_ as a,o as i,c as e,a7 as t}from"./chunks/framework.BCbKzsgW.js";const c=JSON.parse('{"title":"周期任务与定时轮询","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/task-scheduling/triggers/periodic-tasks.md","filePath":"development/common/task-scheduling/triggers/periodic-tasks.md","lastUpdated":1793441194000}'),n={name:"development/common/task-scheduling/triggers/periodic-tasks.md"};function l(h,s,r,p,d,o){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="zhou-qi-ren-wu-yu-ding-shi-lun-xun" tabindex="-1">周期任务与定时轮询 <a class="header-anchor" href="#zhou-qi-ren-wu-yu-ding-shi-lun-xun" aria-label="Permalink to &quot;周期任务与定时轮询&quot;">​</a></h1><p>周期任务按时间规则产生执行实例。定时轮询则反复查询某个状态，例如每隔 10 秒扫描到期订单。一次周期执行可以领取多条业务任务，两者的执行粒度不同。</p><h2 id="gu-ding-jian-ge-yu-ri-li-gui-ze" tabindex="-1">固定间隔与日历规则 <a class="header-anchor" href="#gu-ding-jian-ge-yu-ri-li-gui-ze" aria-label="Permalink to &quot;固定间隔与日历规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>规则</th><th>示例</th><th>需要明确的语义</th></tr></thead><tbody><tr><td>固定频率</td><td>每隔 60 秒开始一轮</td><td>上一轮未结束时是否重叠</td></tr><tr><td>完成后等待</td><td>上一轮结束 60 秒后开始</td><td>耗时会让实际开始时间逐渐后移</td></tr><tr><td>日历规则</td><td>上海时间每天 02:00</td><td>时区、日历边界和错过后的处理</td></tr></tbody></table><p>“每天”与“每隔 24 小时”在涉及夏令时的地区可能产生不同结果。日历计划应保存 IANA 时区，例如 <code>Asia/Shanghai</code>；执行实例同时保存解析后的计划时间，便于追溯当时应该执行哪一轮。</p><p>下面使用 Kubernetes v1.27 起稳定可用的时区配置方式；该特性在 v1.24 为 Alpha，v1.25–v1.26 为默认启用的 Beta，参见官方<a href="https://v1-32.docs.kubernetes.io/docs/reference/command-line-tools-reference/feature-gates-removed/" target="_blank" rel="noreferrer">特性门控历史</a>。其他字段含义见 <a href="https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/#time-zones" target="_blank" rel="noreferrer">CronJob 文档</a>。镜像是示例占位，需要替换为自己的报表程序。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">apiVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">batch/v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">CronJob</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">daily-sales-report</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  schedule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0 2 * * *&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  timeZone</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Asia/Shanghai&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  concurrencyPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Forbid</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  startingDeadlineSeconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1800</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  jobTemplate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      backoffLimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          restartPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Never</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          containers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">report</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">              image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example.invalid/sales-report:replace-me</span></span></code></pre></div><p>这里禁止同一个 CronJob 的活跃 Job 重叠，并允许在计划时间后 30 分钟内补启动。该并发策略不协调其他 CronJob，也不提供业务去重；任务处理逻辑仍要识别相同的报表日期。</p><h2 id="diao-du-ji-huashi-li-yu-chong-shi" tabindex="-1">调度计划、实例与重试 <a class="header-anchor" href="#diao-du-ji-huashi-li-yu-chong-shi" aria-label="Permalink to &quot;调度计划、实例与重试&quot;">​</a></h2><p>假设销售报表每天 02:00 执行：</p><ul><li>计划保存“每天 02:00、上海时区、处理前一天数据”。</li><li>2026-10-27 02:00 对应一轮执行实例，其数据窗口是前一天。</li><li>这一实例第一次失败后，第二次尝试仍处理相同数据窗口。</li></ul><p>实例可以用 <code>schedule_id + scheduled_at</code> 建唯一约束。报表写入也需要按日期或窗口覆盖、合并或版本化，避免同一轮重试后产生两份可见结果。</p><p>补跑历史报表时，业务日期应来自实例参数。直接使用 Worker 启动时的“昨天”，会让延迟多天的任务处理错误日期。</p><h2 id="shang-yi-lun-mei-you-wan-cheng" tabindex="-1">上一轮没有完成 <a class="header-anchor" href="#shang-yi-lun-mei-you-wan-cheng" aria-label="Permalink to &quot;上一轮没有完成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>行为</th><th>代价</th></tr></thead><tbody><tr><td>允许重叠</td><td>新实例按计划启动</td><td>下游并发增加，可能竞争同一数据</td></tr><tr><td>跳过本轮</td><td>活跃实例结束前不再启动</td><td>必须记录漏掉的窗口</td></tr><tr><td>排队执行</td><td>保存新实例，等待资源空闲</td><td>任务可能落后很多轮</td></tr><tr><td>合并执行</td><td>将多个待处理窗口合并</td><td>需要业务允许合并，保留窗口边界</td></tr></tbody></table><p>对需要完整覆盖数据窗口的对账任务，可以保留实例再限流执行；对只关心最新状态的缓存刷新，合并旧轮次可能更合适。中止旧进程也不能撤回它已经提交的写入。</p><h2 id="cuo-guo-zhi-xing-hou-de-bu-pao" tabindex="-1">错过执行后的补跑 <a class="header-anchor" href="#cuo-guo-zhi-xing-hou-de-bu-pao" aria-label="Permalink to &quot;错过执行后的补跑&quot;">​</a></h2><p>系统停机三小时后恢复，计划可能已经错过多轮。补跑需要同时限定时间窗口、最多生成多少实例，以及是否沿用原来的业务日期。</p><p>Kubernetes 官方说明 CronJob 的调度是近似的，特定情况下可能重复创建或漏建 Job，因此任务需要幂等。它对补跑也有自身的检查规则，不能把某种调度器的行为当成所有定时系统的默认承诺。参见 <a href="https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/#job-creation" target="_blank" rel="noreferrer">Job creation</a>。</p><h2 id="lun-xun-jian-ge-yu-sao-miao-cheng-ben" tabindex="-1">轮询间隔与扫描成本 <a class="header-anchor" href="#lun-xun-jian-ge-yu-sao-miao-cheng-ben" aria-label="Permalink to &quot;轮询间隔与扫描成本&quot;">​</a></h2><p>假设到期时间相对扫描周期均匀分布，扫描每 10 秒执行一轮，且没有积压、暂停和查询耗时，单纯等待下一轮扫描的时间平均约 5 秒。真实开始延迟还包括查询、领取、排队和 Worker 等待，不能把 10 秒间隔当成严格上界。</p><p>轮询频率提高前，先检查查询是否只扫描“未完成且已到期”的索引范围。分页扫描应保存推进位置或不断领取状态发生变化的批次，避免用大 OFFSET 重复跳过前面的数据。</p><p>兜底扫描还要有修复目标。例如扫描“到期但没有关闭检查任务的订单”，补建缺失任务；仅重复扫描任务表，发现不了从未创建过的任务。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>Kubernetes：<a href="https://v1-32.docs.kubernetes.io/docs/reference/command-line-tools-reference/feature-gates-removed/" target="_blank" rel="noreferrer">CronJobTimeZone 特性门控历史</a></li><li>Kubernetes：<a href="https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/" target="_blank" rel="noreferrer">CronJob：并发策略、截止时间与调度限制</a></li><li>PostgreSQL 18：<a href="https://www.postgresql.org/docs/18/sql-select.html" target="_blank" rel="noreferrer">SELECT：LIMIT、OFFSET 与行锁</a></li></ul>`,25)])])}const E=a(n,[["render",l]]);export{c as __pageData,E as default};
